{
  "filename": "script.js",
  "content": "(function(){
  const apiBase = '/api';

  // Simple API helper
  const api = {
    get: async (path)=>{
      const resp = await fetch(apiBase+path,{credentials:'same-origin',headers:{'Accept':'application/json'}});
      if(!resp.ok) throw new Error(`GET ${path} failed: ${resp.status}`);
      return resp.json();
    },
    post: async (path,data)=>{
      const resp = await fetch(apiBase+path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(data)});
      if(!resp.ok) throw new Error(`POST ${path} failed: ${resp.status}`);
      return resp.json();
    }
  };

  // Page registry
  const pages = {};
  window.ForgeAI = {
    registerPage: (slug,renderer)=>{ pages[slug]=renderer; }
  };

  // Register core pages (can be overridden/extended later)
  ForgeAI.registerPage('home', async ({root,api})=>{
    root.innerHTML = `<section class="home"><h1>Welcome to CycleTracker</h1><p>Track your cycles, flow and symptoms effortlessly.</p></section>`;
  });

  ForgeAI.registerPage('settings', async ({root,api})=>{
    root.innerHTML = `<section class="settings"><h1>Settings</h1><p>Settings UI will be rendered here.</p></section>`;
  });

  // Sidebar toggle for mobile
  const sidebarToggle = document.getElementById('sidebar-toggle');
  const sidebar = document.getElementById('sidebar');
  if(sidebarToggle && sidebar){
    sidebarToggle.addEventListener('click',()=>{ sidebar.classList.toggle('collapsed'); });
  }

  // Router
  const renderPage = async()=>{
    const hash = location.hash || '#/home';
    const parts = hash.slice(2).split('/'); // remove '#/'
    const slug = parts[0] || 'home';
    const page = pages[slug] || pages['home'];
    const root = document.getElementById('main-content');
    if(!root) return;
    root.innerHTML = '<div class="loading">Loading...</div>';
    try{
      await page({root,api,search:new URLSearchParams(location.search)});
    }catch(e){
      root.innerHTML = `<div class="error">Error: ${e.message}</div>`;
      console.error(e);
    }
    // Update active nav link
    document.querySelectorAll('.nav-link').forEach(a=>{
      const target = a.getAttribute('href');
      a.classList.toggle('active', target===`#/${slug}`);
    });
  };

  window.addEventListener('hashchange',renderPage);
  window.addEventListener('load',renderPage);
})();
"
